#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: spike for issue #97 (does an interactive auto-mode session run gh and
# git push under managed policy?). Results land in $ENV_FILE as KEY=VALUE lines.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=17
# The library defaults ENV_FILE to .env; force a dedicated results file instead.
ENV_FILE="${SPIKE_RESULTS:-spike-97-results.env}"

# Resume support: START_AT=10 ./spike-97-forge-session.sh (or pass the number as
# the first argument). Run it from the directory holding the results file.
# Supported start points: 1-10 and 17 (clean up).
START_AT="${START_AT:-${1:-1}}"
BRANCH="spike/forge-97"
CODEX_BRANCH="spike/forge-97-codex"
PR_NUMBER=""; CODEX_PR_NUMBER=""; CODEX_RUN=0
if (( START_AT > 1 )); then
  if (( START_AT > 10 && START_AT != 17 )); then
    warn "can only resume at stages 1-10 or 17 (stages 11-16 depend on stage 10)"; exit 1
  fi
  [[ -f "$ENV_FILE" ]] || { warn "no $ENV_FILE here; run from the directory with your earlier results"; exit 1; }
  FIXTURE_REPO="$(_existing FIXTURE_REPO || true)"
  FIXTURE_ISSUE="$(_existing FIXTURE_ISSUE || true)"
  WT="$(_existing WORKTREE || true)"
  PR_NUMBER="$(_existing PR_NUMBER || true)"
  CODEX_PR_NUMBER="$(_existing CODEX_PR_NUMBER || true)"
  if [[ -z "$FIXTURE_REPO" || -z "$FIXTURE_ISSUE" ]]; then
    warn "$ENV_FILE has no FIXTURE_REPO/FIXTURE_ISSUE; start from stage 1 or 2"; exit 1
  fi
  CODEX_WT="$(cd "$FIXTURE_REPO/.." && pwd)/spike-97-codex-worktree"
fi

# record_action PREFIX "what you asked": asks the standard three questions and
# writes PREFIX_RESULT, PREFIX_SANDBOX, PREFIX_NOTE.
record_action() {
  local p="$1" engine="${2:-claude}" choice="" result=""
  say ""
  say "What happened?"
  step "1  succeeded with no prompt"
  step "2  prompted, and I approved it"
  step "3  succeeded after the auto classifier approved it (no human prompt)"
  step "4  denied / failed"
  while :; do
    printf '  %sChoice [1-4]:%s ' "$BOLD" "$RESET"; read -r choice || true
    case "$choice" in
      1) result="succeeded-no-prompt"; break ;;
      2) result="prompted-human-approved"; break ;;
      3) result="classifier-approved"; break ;;
      4) result="denied-or-failed"; break ;;
      *) warn "enter 1, 2, 3 or 4" ;;
    esac
  done
  say ""
  say "How did the command run with respect to the sandbox?"
  if [[ "$engine" == "codex" ]]; then
    note "How to tell: an approval prompt asking to run a command outside the sandbox / with"
    note "network access means it escalated. No prompt and it worked means it ran sandboxed."
    note "If you launched codex with a full-access sandbox mode, choose 3."
    step "1  ran inside the sandbox (no approval)"
    step "2  failed or needed more access, then ran OUTSIDE the sandbox after an approval"
    step "3  sandbox is off (full-access mode)"
    step "4  unsure"
  else
    note "How to tell: press Ctrl-O in the session to show the tool calls. A Bash call that was"
    note "retried outside the sandbox shows 'dangerouslyDisableSandbox: true' or the prompt said"
    note "'run outside the sandbox'. Type /sandbox in the session to see whether the sandbox is"
    note "enabled at all. If the command simply ran with none of that, it ran sandboxed."
    step "1  ran inside the sandbox (no retry)"
    step "2  failed in the sandbox, then was retried OUTSIDE the sandbox"
    step "3  the sandbox is not enabled in this session (/sandbox shows off)"
    step "4  unsure"
  fi
  local sb=""
  while :; do
    printf '  %sChoice [1-4]:%s ' "$BOLD" "$RESET"; read -r choice || true
    case "$choice" in
      1) sb="sandboxed"; break ;;
      2) sb="unsandboxed-retry"; break ;;
      3) sb="sandbox-disabled"; break ;;
      4) sb="unsure"; break ;;
      *) warn "enter 1, 2, 3 or 4" ;;
    esac
  done
  ask "${p}_NOTE" "Exact error text or anything odd (Enter for none):"
  local note_var="${p}_NOTE"
  printf -v "${p}_RESULT" '%s' "$result"
  write_env "${p}_RESULT" "$result"
  write_env "${p}_SANDBOX" "$sb"
  write_env "${p}_NOTE" "${!note_var}"
}

# seed_commit_if_failed PREFIX WORKTREE FILE MSG: if the agent could not commit
# (that is itself a spike result, already recorded), offer to make the commit
# from this shell so the remaining actions can still be tested.
seed_commit_if_failed() {
  local p="$1" wt="$2" file="$3" msg="$4" rv="${1}_RESULT"
  if [[ "${!rv}" == "denied-or-failed" ]] || ! git -C "$wt" log -1 --format=%s 2>/dev/null | grep -qx "$msg"; then
    warn "no commit from the agent. That result is recorded; later steps need a commit to push."
    if confirm "Make the commit from this shell (outside the agent) so the remaining actions can run?"; then
      printf 'spike\n' > "$wt/$file"
      git -C "$wt" add "$file" && git -C "$wt" commit -q -m "$msg" && write_env "${p}_SEEDED_BY_WIZARD" "yes"
    else
      write_env "${p}_SEEDED_BY_WIZARD" "no"
    fi
  fi
}

banner "Spike #97: interactive auto-mode session vs gh and git push"
_STAGE_INDEX=$((START_AT - 1))

# ── 1 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 1 )); then
stage "Preflight: what machine is this?"
say "Collecting facts automatically. Nothing is changed."
write_env OS "$(uname -sm)"
write_env CLAUDE_VERSION "$(claude --version 2>&1 | head -n1 || echo missing)"
write_env CODEX_VERSION "$(codex --version 2>&1 | head -n1 || echo missing)"
write_env TMUX_VERSION "$(tmux -V 2>&1 | head -n1 || echo missing)"
write_env GH_VERSION "$(gh --version 2>&1 | head -n1 || echo missing)"
write_env GH_AUTH "$(gh auth status 2>&1 | grep -m1 -E 'Logged in|not logged' || echo unknown)"
if [[ -f "$HOME/.claude/remote-settings.json" || -d "/Library/Application Support/ClaudeCode" || -d /etc/claude-code ]]; then
  write_env MANAGED_POLICY_FOUND "yes"
else
  write_env MANAGED_POLICY_FOUND "no"
fi
pause "Looks right? Press Enter."
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 2 )); then
stage "Pick the fixture repo and issue"
say "Use the fixture repo (a throwaway GitHub repo you don't mind a draft PR in)."
ask FIXTURE_REPO "Path to a local clone of the fixture repo:"
ask FIXTURE_ISSUE "Number of an existing issue in that repo:"
[[ -d "$FIXTURE_REPO/.git" || -f "$FIXTURE_REPO/.git" ]] || { warn "not a git repo: $FIXTURE_REPO"; exit 1; }
write_env FIXTURE_REPO "$FIXTURE_REPO"
write_env FIXTURE_ISSUE "$FIXTURE_ISSUE"
BRANCH="spike/forge-97"
WT="$(cd "$FIXTURE_REPO/.." && pwd)/spike-97-worktree"
if [[ -d "$WT" ]]; then
  note "worktree already exists at $WT, reusing it"
elif confirm "Create worktree $WT on new branch $BRANCH?"; then
  git -C "$FIXTURE_REPO" worktree add -b "$BRANCH" "$WT"
else
  warn "worktree needed; aborting"; exit 1
fi
write_env WORKTREE "$WT"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 3 )); then
stage "Launch the interactive session"
say "In a SECOND terminal, start the session exactly as the Archwright is launched:"
step "cd $WT"
step "run your Archwright launch command (or: claude --permission-mode auto)"
step "do NOT pre-approve anything, and keep it in auto mode"
ask LAUNCH_COMMAND "Paste the exact command you used to launch it:"
ask PERMISSION_MODE "Permission mode shown in the session (auto/default/other):"
write_env LAUNCH_COMMAND "$LAUNCH_COMMAND"
write_env PERMISSION_MODE "$PERMISSION_MODE"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 4 )); then
stage "Action 1/5: gh issue view"
say "Paste this into the session:"
note "Run exactly: gh issue view $FIXTURE_ISSUE   Report what happened. If it fails, do not try alternatives."
pause "Press Enter once the session has finished."
record_action A1_ISSUE_VIEW
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 5 )); then
stage "Action 2/5: git commit in the worktree"
say "Paste this into the session:"
note "Create a file spike-97.txt containing 'spike', then run: git add spike-97.txt && git commit -m 'spike 97'. Report what happened. If it fails, do not try alternatives."
pause "Press Enter once the session has finished."
record_action A2_COMMIT
seed_commit_if_failed A2_COMMIT "$WT" spike-97.txt "spike 97"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 6 )); then
stage "Action 3/5: git push"
say "Paste this into the session:"
note "Run exactly: git push -u origin $BRANCH   Report what happened. If it fails, do not try alternatives."
pause "Press Enter once the session has finished."
record_action A3_PUSH
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 7 )); then
stage "Action 4/5: gh pr create"
say "Skip this if the push failed (say 4 and note 'skipped: no branch')."
say "Paste this into the session:"
note "Run exactly: gh pr create --draft --title spike --body spike   Report what happened and the PR number. If it fails, do not try alternatives."
pause "Press Enter once the session has finished."
record_action A4_PR_CREATE
ask PR_NUMBER "PR number created (Enter if none):"
write_env PR_NUMBER "${PR_NUMBER:-}"
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 8 )); then
stage "Action 5/5: gh pr comment"
say "Skip if there is no PR."
say "Paste this into the session:"
note "Run exactly: gh pr comment ${PR_NUMBER:-<n>} --body spike   Report what happened. If it fails, do not try alternatives."
pause "Press Enter once the session has finished."
record_action A5_PR_COMMENT
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
if (( START_AT <= 9 )); then
stage "tmux check"
if command -v tmux >/dev/null 2>&1; then
  say "Starting and stopping a throwaway detached session (no claude involved)."
  if tmux new-session -d -s spike97 'sleep 30' 2>/dev/null && tmux has-session -t spike97 2>/dev/null; then
    write_env TMUX_SESSION_TEST "ok"
  else
    write_env TMUX_SESSION_TEST "failed"
  fi
  tmux kill-session -t spike97 2>/dev/null || true
  say "Now optionally try launching your Archwright command inside tmux yourself:"
  step "tmux new -s spike97b   then run the launch command; detach with Ctrl-b d"
  ask TMUX_CLAUDE_NOTE "Did the session run normally inside tmux? Notes (Enter to skip):"
  write_env TMUX_CLAUDE_NOTE "${TMUX_CLAUDE_NOTE:-}"
else
  warn "tmux is not installed on this machine"
  write_env TMUX_SESSION_TEST "not-installed"
fi
fi

# ── 10 ────────────────────────────────────────────────────────────────────
if (( START_AT <= 10 )); then
stage "Codex (optional): worktree for the interactive session"
CODEX_BRANCH="spike/forge-97-codex"
CODEX_WT="$(cd "$FIXTURE_REPO/.." && pwd)/spike-97-codex-worktree"
CODEX_PR_NUMBER=""
CODEX_RUN=0
CODEX_STAGES=6   # stages after this one that belong to the Codex run
if command -v codex >/dev/null 2>&1 && confirm "Run the Codex part of the spike?"; then
  CODEX_RUN=1
  say "Codex gets its own worktree and branch so the Claude commit does not interfere."
  if [[ -d "$CODEX_WT" ]]; then
    note "worktree already exists at $CODEX_WT, reusing it"
  else
    git -C "$FIXTURE_REPO" worktree add -b "$CODEX_BRANCH" "$CODEX_WT"
  fi
  write_env CODEX_WORKTREE "$CODEX_WT"
  say ""
  say "This tests a NON-headless codex session as a Forge agent: launch it exactly as the"
  say "Archwright is launched, with no extra permission or sandbox flags."
  pause "Press Enter to continue."
else
  write_env CODEX_RESULTS "skipped"
  _STAGE_INDEX=$((_STAGE_INDEX + CODEX_STAGES))
fi
fi

# ── 11-16 ─────────────────────────────────────────────────────────────────
if (( CODEX_RUN )); then
  # ── 11 ──────────────────────────────────────────────────────────────────
  stage "Codex: launch the interactive session"
  say "In a SECOND terminal:"
  step "cd $CODEX_WT"
  step "launch codex exactly as the Archwright is launched (interactive, no extra flags)"
  step "do NOT pre-approve anything"
  ask CODEX_LAUNCH_COMMAND "Paste the exact command you used:"
  ask CODEX_APPROVAL_MODE "Approval policy shown in the session (e.g. on-request, never):"
  ask CODEX_SANDBOX_MODE "Sandbox mode shown (read-only, workspace-write, danger-full-access, unsure):"
  write_env CODEX_LAUNCH_COMMAND "$CODEX_LAUNCH_COMMAND"
  write_env CODEX_APPROVAL_MODE "$CODEX_APPROVAL_MODE"
  write_env CODEX_SANDBOX_MODE "$CODEX_SANDBOX_MODE"

  # ── 12 ──────────────────────────────────────────────────────────────────
  stage "Codex action 1/5: gh issue view"
  say "Paste this into the codex session:"
  note "Run exactly: gh issue view $FIXTURE_ISSUE   Report what happened. If it fails, do not try alternatives."
  pause "Press Enter once codex has finished."
  record_action CX1_ISSUE_VIEW codex

  # ── 13 ──────────────────────────────────────────────────────────────────
  stage "Codex action 2/5: git commit in the worktree"
  say "Paste this into the codex session:"
  note "Create a file spike-97-codex.txt containing 'spike', then run: git add spike-97-codex.txt && git commit -m 'spike 97 codex'. Report what happened. If it fails, do not try alternatives."
  pause "Press Enter once codex has finished."
  record_action CX2_COMMIT codex
  seed_commit_if_failed CX2_COMMIT "$CODEX_WT" spike-97-codex.txt "spike 97 codex"

  # ── 14 ──────────────────────────────────────────────────────────────────
  stage "Codex action 3/5: git push"
  say "Paste this into the codex session:"
  note "Run exactly: git push -u origin $CODEX_BRANCH   Report what happened. If it fails, do not try alternatives."
  pause "Press Enter once codex has finished."
  record_action CX3_PUSH codex

  # ── 15 ──────────────────────────────────────────────────────────────────
  stage "Codex action 4/5: gh pr create"
  say "Skip if the push failed (choose 4 and note 'skipped: no branch')."
  say "Paste this into the codex session:"
  note "Run exactly: gh pr create --draft --title spike-codex --body spike   Report what happened and the PR number. If it fails, do not try alternatives."
  pause "Press Enter once codex has finished."
  record_action CX4_PR_CREATE codex
  ask CODEX_PR_NUMBER "PR number created (Enter if none):"
  write_env CODEX_PR_NUMBER "${CODEX_PR_NUMBER:-}"

  # ── 16 ──────────────────────────────────────────────────────────────────
  stage "Codex action 5/5: gh pr comment"
  say "Skip if there is no PR."
  say "Paste this into the codex session:"
  note "Run exactly: gh pr comment ${CODEX_PR_NUMBER:-<n>} --body spike   Report what happened. If it fails, do not try alternatives."
  pause "Press Enter once codex has finished."
  record_action CX5_PR_COMMENT codex
fi

# ── 17 ────────────────────────────────────────────────────────────────────
if (( START_AT <= 17 )); then
stage "Clean up"
say "Closes the draft PRs, deletes the remote branches and removes the worktrees."
if confirm "Clean up now?"; then
  for pr in "${PR_NUMBER:-}" "${CODEX_PR_NUMBER:-}"; do
    [[ -n "$pr" ]] && { (cd "$FIXTURE_REPO" && gh pr close "$pr" --delete-branch) || true; }
  done
  for br in "$BRANCH" "$CODEX_BRANCH"; do
    git -C "$FIXTURE_REPO" push origin --delete "$br" >/dev/null 2>&1 || true
  done
  for wt in "$WT" "$CODEX_WT"; do
    [[ -d "$wt" ]] && { git -C "$FIXTURE_REPO" worktree remove --force "$wt" || true; }
  done
  for br in "$BRANCH" "$CODEX_BRANCH"; do
    git -C "$FIXTURE_REPO" branch -D "$br" >/dev/null 2>&1 || true
  done
  say "cleaned up"
else
  warn "left in place; remove the PRs, branches $BRANCH and $CODEX_BRANCH, and worktrees $WT and $CODEX_WT by hand"
fi
fi

finish
printf '  %sResults file:%s %s\n\n' "$BOLD" "$RESET" "$ENV_FILE"
cat "$ENV_FILE"
printf '\n  Paste the block above back into the Claude conversation.\n\n'
